styles.text:
.rs-icon { display: inline-flex; -webkit-box-align: center; align-items: center; text-rendering: optimizelegibility; -webkit-font-smoothing: antialiased; vertical-align: middle; }
.rs-icon[tabindex] { cursor: pointer; }
.rs-icon-spin { animation: 2s linear 0s infinite normal none running icon-spin; }
.rs-icon-pulse { animation: 1s steps(8) 0s infinite normal none running icon-spin; }
.rs-icon-flip-horizontal { transform: scaleX(-1); }
.rs-icon-flip-vertical { transform: scaleY(-1); }
@-webkit-keyframes icon-spin { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(359deg); }
}
@keyframes icon-spin { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(359deg); }
}

